import test from 'node:test';import assert from 'node:assert/strict';import {defaultConstruction,normalizeConstruction,constructionProjects,constructionKits,constructionView,constructionDispatch,openBuild,placeBuild,buildAction,testBuild,buildPipePorts,buildFixed,constructionPower} from '../src/construction.js';import {farmView,normalizeFarm} from '../src/farm.js';
test('all six prefab models can be assembled, tested, reset and repeated without losing kits',()=>{const s=defaultConstruction();for(const [id,p]of Object.entries(constructionProjects).filter(([,p])=>p.kit)){openBuild(s,id);assert.equal(testBuild(s).ok,false);for(const [x,y,part,r]of p.solution){s.selected=part;s.rotation=r;assert.ok(placeBuild(s,x,y))}if(id==='power')s.power=true;assert.equal(testBuild(s).ok,true,id);assert.ok(s.kits.includes(p.kit));buildAction(s,'reset');assert.equal(s.boards[id].filter(Boolean).length,0);assert.ok(s.kits.includes(p.kit));buildAction(s,'robot');assert.equal(testBuild(s).ok,true);assert.equal(s.kits.filter(k=>k===p.kit).length,1)}});
test('pipe openings, valve state and supply/return circuit are actually checked',()=>{const s=defaultConstruction();openBuild(s,'pipes');buildAction(s,'robot');assert.equal(testBuild(s).ok,true);s.boards.pipes[2*12+5].rotation=1;assert.equal(testBuild(s).ok,false);assert.deepEqual(buildPipePorts({part:'elbow',rotation:1}),[1,2]);openBuild(s,'water');s.selected='valve';placeBuild(s,6,2);assert.equal(testBuild(s).ok,false);placeBuild(s,6,2);assert.equal(testBuild(s).ok,true);openBuild(s,'power');s.power=true;assert.equal(constructionPower(s),false);buildAction(s,'robot');assert.equal(constructionPower(s),true);s.boards.power[3*12+5]=null;assert.equal(testBuild(s).ok,false);});
test('fixed supports resist edits, undo restores placements, and reload validates saved boards',()=>{const s=defaultConstruction();openBuild(s,'bridge');assert.ok(buildFixed('bridge',0,4));assert.equal(placeBuild(s,0,4),false);placeBuild(s,2,3);assert.ok(s.boards.bridge[38]);buildAction(s,'undo');assert.equal(s.boards.bridge[38],null);placeBuild(s,2,3);const saved=normalizeConstruction(s);assert.equal(saved.active,null);assert.equal(saved.boards.bridge[38].part,'beam');assert.deepEqual(normalizeConstruction({boards:{bridge:[{part:'bad'}]},kits:['fake']}).kits,[])});
test('machines award distinct reusable parts and gate the three-stage training elevator',()=>{const s=defaultConstruction();constructionDispatch(s,{type:'foundation'});assert.equal(s.elevator,0);for(const id of Object.keys(constructionProjects).filter(id=>id!=='free')){openBuild(s,id);buildAction(s,'robot');testBuild(s)}for(const machine of ['printer','crane','robot'])for(let i=0;i<3;i++)constructionDispatch(s,{type:'machine',value:machine});assert.deepEqual(new Set(s.kits),new Set(constructionKits));for(let i=0;i<3;i++)constructionDispatch(s,{type:'foundation'});assert.equal(s.elevator,3);constructionDispatch(s,{type:'orbit'});assert.equal(s.orbit,true);assert.equal(s.kits.length,9);const saved=normalizeConstruction(s);assert.equal(saved.elevator,3);assert.equal(saved.orbit,false);});
test('native page choices stay within six and built kits can be saved at the farm',()=>{const s=defaultConstruction();s.kits=[...constructionKits];for(const page of ['projects','parts','parts:3','parts:6','elevator','printer','crane','robot','pipes','power']){const v=constructionView(s,page);assert.ok(v.title&&v.text&&v.art);assert.ok(v.actions.length<=6,page)}const f=normalizeFarm({constructionModules:['pipe-kit','fake','robot-kit','pipe-kit']});assert.deepEqual(f.constructionModules,['pipe-kit','robot-kit']);assert.match(farmView(f,'modules').body,/pipe kit/)});

test('free building has no required answer and reset/demonstrations can be undone',()=>{const s=defaultConstruction();openBuild(s,'free');s.selected='block';placeBuild(s,2,2);const original=JSON.stringify(s.boards.free);buildAction(s,'reset');assert.equal(s.boards.free.filter(Boolean).length,0);buildAction(s,'undo');assert.equal(JSON.stringify(s.boards.free),original);buildAction(s,'robot');assert.ok(s.boards.free[26]);buildAction(s,'undo');assert.equal(JSON.stringify(s.boards.free),original);assert.equal(testBuild(s).ok,true);assert.equal(s.kits.length,0)});
